    {
      "path": "scripts/package_research2.py",
      "old": "def validate_manifest(data: Any, label: str, rel: str,\n                      expected_role: Optional[int]) -> int:\n    if not isinstance(data, dict):\n        raise PackageError('%s (%s): manifest is not a JSON object' % (label, rel))\n    status = data.get('status')\n    if status != 'passed':\n        raise PackageError('%s (%s): status is %r, want passed' % (label, rel, status))\n    commit = data.get('platform_commit')\n    if commit != EXPECTED_PLATFORM_COMMIT:\n        raise PackageError('%s (%s): platform_commit is %r, want %s' %\n                           (label, rel, commit, EXPECTED_PLATFORM_COMMIT))\n    lock = data.get('sources_lock_sha256')\n    if not isinstance(lock, str) or not HEX64_RE.fullmatch(lock):\n        raise PackageError('%s (%s): sources_lock_sha256 is missing or not a sha256' %\n                           (label, rel))\n    profile = data.get('profile')\n    if not isinstance(profile, dict):\n        raise PackageError('%s (%s): profile must be an object' % (label, rel))\n    role = profile.get('research_role')\n    if role not in (1, 2):\n        raise PackageError('%s (%s): profile.research_role must be 1 or 2, got %r' %\n                           (label, rel, role))\n    if expected_role is not None and role != expected_role:\n        raise PackageError('%s (%s): profile.research_role is %s, want %s' %\n                           (label, rel, role, expected_role))\n    return int(role)",
      "new": "def validate_manifest(data: Any, label: str, rel: str,\n                      expected_role: Optional[int],\n                      expected_platform_commit: str) -> int:\n    if not isinstance(data, dict):\n        raise PackageError('%s (%s): manifest is not a JSON object' % (label, rel))\n    status = data.get('status')\n    if status != 'passed':\n        raise PackageError('%s (%s): status is %r, want passed' % (label, rel, status))\n    commit = data.get('platform_commit')\n    if commit != expected_platform_commit:\n        raise PackageError('%s (%s): platform_commit is %r, want %s' %\n                           (label, rel, commit, expected_platform_commit))\n    lock = data.get('sources_lock_sha256')\n    if not isinstance(lock, str) or not HEX64_RE.fullmatch(lock):\n        raise PackageError('%s (%s): sources_lock_sha256 is missing or not a sha256' %\n                           (label, rel))\n    profile = data.get('profile')\n    if not isinstance(profile, dict):\n        raise PackageError('%s (%s): profile must be an object' % (label, rel))\n    role = profile.get('research_role')\n    if role not in (1, 2):\n        raise PackageError('%s (%s): profile.research_role must be 1 or 2, got %r' %\n                           (label, rel, role))\n    if expected_role is not None and role != expected_role:\n        raise PackageError('%s (%s): profile.research_role is %s, want %s' %\n                           (label, rel, role, expected_role))\n    return int(role)"
    },
    {
      "path": "scripts/package_research2.py",
      "old": "def load_manifest(repo: pathlib.Path, rel: str, label: str,\n                  expected_role: Optional[int] = None) -> Dict[str, Any]:\n    path = resolve_rel(repo, rel)\n    if not path.is_file():\n        raise PackageError('%s is missing: %s' % (label, rel))\n    data = read_json(path, label)\n    role = validate_manifest(data, label, rel, expected_role)\n    return {'label': label, 'rel': rel, 'path': path, 'data': data, 'role': role,\n            'sha256': sha256_file(path)}",
      "new": "def load_manifest(repo: pathlib.Path, rel: str, label: str,\n                  expected_role: Optional[int] = None,\n                  expected_platform_commit: Optional[str] = None) -> Dict[str, Any]:\n    path = resolve_rel(repo, rel)\n    if not path.is_file():\n        raise PackageError('%s is missing: %s' % (label, rel))\n    data = read_json(path, label)\n    if expected_platform_commit is None:\n        raise PackageError('%s (%s): missing expected platform commit' % (label, rel))\n    role = validate_manifest(data, label, rel, expected_role,\n                             expected_platform_commit)\n    return {'label': label, 'rel': rel, 'path': path, 'data': data, 'role': role,\n            'sha256': sha256_file(path)}"
    },
    {
      "path": "scripts/package_research2.py",
      "old": "def verify_manifest_artifacts(repo: pathlib.Path, entry: Dict[str, Any],\n                              verified: Dict[str, str]) -> None:",
      "new": "def validate_lock_pair(software_path: pathlib.Path,\n                       hardware_path: pathlib.Path) -> Tuple[Dict[str, Any], Dict[str, Any]]:\n    software = read_json(software_path, 'software sources lock')\n    hardware = read_json(hardware_path, 'hardware sources lock')\n    if not isinstance(software, dict) or not isinstance(hardware, dict):\n        raise PackageError('sources locks must be JSON objects')\n    software_top = dict(software)\n    hardware_top = dict(hardware)\n    software_components = software_top.pop('components', None)\n    hardware_components = hardware_top.pop('components', None)\n    if software_top != hardware_top:\n        raise PackageError('sources locks differ outside components')\n    if not isinstance(software_components, list) or not isinstance(hardware_components, list):\n        raise PackageError('sources locks must have a components list')\n    if len(software_components) != len(hardware_components):\n        raise PackageError('sources locks have different component counts')\n    seen = set()\n    software_cva6 = None\n    hardware_cva6 = None\n    for software_component, hardware_component in zip(software_components,\n                                                      hardware_components):\n        if not isinstance(software_component, dict) or not isinstance(hardware_component, dict):\n            raise PackageError('sources lock component is not an object')\n        path = software_component.get('path')\n        if not isinstance(path, str) or not path:\n            raise PackageError('sources lock component has no path')\n        if path in seen:\n            raise PackageError('sources lock has a duplicate component: %s' % path)\n        seen.add(path)\n        if hardware_component.get('path') != path:\n            raise PackageError('sources lock component order differs at %s' % path)\n        for key in sorted(set(software_component) | set(hardware_component)):\n            if key == 'commit' and path == CVA6_LOCK_PATH:\n                continue\n            if software_component.get(key) != hardware_component.get(key):\n                raise PackageError('sources lock component %s differs in %s' %\n                                   (path, key))\n        if path == CVA6_LOCK_PATH:\n            software_cva6 = software_component\n            hardware_cva6 = hardware_component\n    if software_cva6 is None or hardware_cva6 is None:\n        raise PackageError('sources locks do not contain %s' % CVA6_LOCK_PATH)\n    if software_cva6.get('commit') != EXPECTED_SOFTWARE_CVA6_COMMIT:\n        raise PackageError('software lock cva6 commit is %r, want %s' %\n                           (software_cva6.get('commit'), EXPECTED_SOFTWARE_CVA6_COMMIT))\n    if hardware_cva6.get('commit') != EXPECTED_HARDWARE_CVA6_COMMIT:\n        raise PackageError('hardware lock cva6 commit is %r, want %s' %\n                           (hardware_cva6.get('commit'), EXPECTED_HARDWARE_CVA6_COMMIT))\n    return software, hardware\n\n\ndef verify_manifest_artifacts(repo: pathlib.Path, entry: Dict[str, Any],\n                              verified: Dict[str, str]) -> None:"
