    },
    {
      "path": "scripts/package_research2.py",
      "old": "    # 2. sources lock -----------------------------------------------------\n    lock_path = resolve_rel(repo, SOURCES_LOCK_REL)\n    if not lock_path.is_file():\n        raise PackageError('sources lock is missing: %s' % SOURCES_LOCK_REL)\n    lock_sha = sha256_file(lock_path)\n    for entry in manifests:\n        declared = entry['data']['sources_lock_sha256'].lower()\n        if declared != lock_sha:\n            raise PackageError('%s (%s): sources_lock_sha256 %s does not match the '\n                               'current %s hash %s' %\n                               (entry['label'], entry['rel'], declared,\n                                SOURCES_LOCK_REL, lock_sha))",
      "new": "    # 2. sources locks ----------------------------------------------------\n    software_lock_path = resolve_rel(repo, SOFTWARE_SOURCES_LOCK_REL)\n    if not software_lock_path.is_file():\n        raise PackageError('software sources lock is missing: %s' %\n                           SOFTWARE_SOURCES_LOCK_REL)\n    hardware_lock_path = resolve_rel(repo, SOURCES_LOCK_REL)\n    if not hardware_lock_path.is_file():\n        raise PackageError('hardware sources lock is missing: %s' %\n                           SOURCES_LOCK_REL)\n    software_lock_sha = sha256_file(software_lock_path)\n    hardware_lock_sha = sha256_file(hardware_lock_path)\n    if software_lock_sha != EXPECTED_SOFTWARE_LOCK_SHA256:\n        raise PackageError('software sources lock %s hash is %s, want %s' %\n                           (SOFTWARE_SOURCES_LOCK_REL, software_lock_sha,\n                            EXPECTED_SOFTWARE_LOCK_SHA256))\n    if software_lock_sha == hardware_lock_sha:\n        raise PackageError('software and hardware sources locks are identical; '\n                           'the hardware lock must carry the new cva6 commit')\n    declared_software = software['data']['sources_lock_sha256'].lower()\n    if declared_software != software_lock_sha:\n        raise PackageError('%s (%s): sources_lock_sha256 %s does not match the '\n                           'saved software lock %s hash %s' %\n                           (software['label'], software['rel'], declared_software,\n                            SOFTWARE_SOURCES_LOCK_REL, software_lock_sha))\n    for role in (1, 2):\n        declared_hardware = fpga[role]['data']['sources_lock_sha256'].lower()\n        if declared_hardware != hardware_lock_sha:\n            raise PackageError('%s (%s): sources_lock_sha256 %s does not match the '\n                               'current hardware lock %s hash %s' %\n                               (fpga[role]['label'], fpga[role]['rel'],\n                                declared_hardware, SOURCES_LOCK_REL, hardware_lock_sha))\n    validate_lock_pair(software_lock_path, hardware_lock_path)\n    software_lock_delivery_rel = ('provenance/' +\n                                  pathlib.PurePosixPath(SOFTWARE_SOURCES_LOCK_REL).name)\n    hardware_lock_delivery_rel = ('provenance/' +\n                                  pathlib.PurePosixPath(SOURCES_LOCK_REL).name)"
    },
    {
      "path": "scripts/package_research2.py",
      "old": "    # 3. artifacts listed by every manifest -------------------------------\n    verified_artifacts: Dict[str, str] = {}\n    for entry in manifests:\n        verify_manifest_artifacts(repo, entry, verified_artifacts)",
      "new": "    # 3. artifacts listed by every manifest -------------------------------\n    verified_artifacts: Dict[str, str] = {}\n    for entry in manifests:\n        verify_manifest_artifacts(repo, entry, verified_artifacts)\n    software_artifacts = software['data'].get('artifacts')\n    if software_artifacts != EXPECTED_SOFTWARE_ARTIFACTS:\n        raise PackageError('software manifest artifacts differ from the original '\n                           'software artifact set')"
    },
    {
      "path": "scripts/package_research2.py",
      "old": "    add('provenance/' + SOURCES_LOCK_REL, lock_path)\n    for entry in manifests:",
      "new": "    add(software_lock_delivery_rel, software_lock_path)\n    add(hardware_lock_delivery_rel, hardware_lock_path)\n    for entry in manifests:"
    },
    {
      "path": "scripts/package_research2.py",
      "old": "        'provenance': {\n            'host_tools_commit': host_commit,\n            'hardware_platform_commit': fpga[1]['data']['platform_commit'],\n            'software_platform_commit': software['data']['platform_commit'],\n            'sources_lock_sha256': lock_sha,\n            'manifests': {\n                'software': 'provenance/manifests/' +\n                            pathlib.PurePosixPath(software['rel']).name,\n                'fpga_role1': 'provenance/manifests/' +\n                              pathlib.PurePosixPath(fpga[1]['rel']).name,\n                'fpga_role2': 'provenance/manifests/' +\n                              pathlib.PurePosixPath(fpga[2]['rel']).name,\n            },\n        },",
      "new": "        'provenance': {\n            'host_tools_commit': host_commit,\n            'software_platform_commit': software['data']['platform_commit'],\n            'hardware_platform_commit': fpga[1]['data']['platform_commit'],\n            'software_sources_lock': {\n                'path': software_lock_delivery_rel,\n                'source_path': SOFTWARE_SOURCES_LOCK_REL,\n                'sha256': software_lock_sha,\n            },\n            'hardware_sources_lock': {\n                'path': hardware_lock_delivery_rel,\n                'source_path': SOURCES_LOCK_REL,\n                'sha256': hardware_lock_sha,\n            },\n            'compatibility_note': COMPATIBILITY_NOTE,\n            'manifests': {\n                'software': 'provenance/manifests/' +\n                            pathlib.PurePosixPath(software['rel']).name,\n                'fpga_role1': 'provenance/manifests/' +\n                              pathlib.PurePosixPath(fpga[1]['rel']).name,\n                'fpga_role2': 'provenance/manifests/' +\n                              pathlib.PurePosixPath(fpga[2]['rel']).name,\n            },\n        },"
    },
    {
      "path": "scripts/package_research2.py",
      "old": "        'note': ('host-side package only; the plans carry unresolved templates and '\n                 'no calibration selection has been applied'),",
      "new": "        'note': ('host-side package only; the plans carry unresolved templates and '\n                 'no calibration selection has been applied; the existing software '\n                 'build is reused unchanged and is not rebuilt; ' + COMPATIBILITY_NOTE),"
