    {
      "path": "scripts/package_research2.py",
      "old": "        'sources_lock': {'path': SOURCES_LOCK_REL, 'sha256': lock_sha},",
      "new": "        'software_sources_lock': {'path': SOFTWARE_SOURCES_LOCK_REL,\n                                  'sha256': software_lock_sha},\n        'hardware_sources_lock': {'path': SOURCES_LOCK_REL,\n                                  'sha256': hardware_lock_sha},"
    },
    {
      "path": "scripts/package_research2.py",
      "old": "        'host_tools_commit': host_commit,\n        'sources_lock_sha256': lock_sha,\n        'plans': {stage: plan_count[stage] for stage, _expected in PLAN_COUNTS},",
      "new": "        'host_tools_commit': host_commit,\n        'software_platform_commit': software['data']['platform_commit'],\n        'hardware_platform_commit': fpga[1]['data']['platform_commit'],\n        'software_sources_lock_sha256': software_lock_sha,\n        'hardware_sources_lock_sha256': hardware_lock_sha,\n        'plans': {stage: plan_count[stage] for stage, _expected in PLAN_COUNTS},"
